    --yellow: #f7c600;
    --black: #0d0d0d;
    --white: #f4f2ec;
    --line: 10px;
    --font-display: "Archivo Black", "Arial Black", sans-serif;
    --font-body: "Jost", "Futura", "Trebuchet MS", sans-serif;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: var(--font-body);
    background: var(--white);
    color: var(--black);
    line-height: 1.6;
    font-weight: 400;
  }
  h1, h2, h3 { font-family: var(--font-display); line-height: 1.05; text-transform: uppercase; }
  a { color: var(--blue); }
  a:focus-visible, .cta:focus-visible {
    outline: 4px solid var(--yellow);
    outline-offset: 3px;
  }

  /* ---------- Header ---------- */
  header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
