    background: var(--white);
    position: sticky;
    top: 0;
    z-index: 10;
    flex-wrap: wrap;
  }
  .brand {
    font-family: var(--font-display);
    text-transform: uppercase;
    letter-spacing: .04em;
    font-size: 1rem;
    color: var(--black);
    text-decoration: none;
  }
  .swatches { display: flex; gap: .5rem; }
  .swatch { width: 18px; height: 18px; border: 3px solid var(--black); }
  .swatch.r { background: var(--red); }
  .swatch.b { background: var(--blue); }
  .swatch.y { background: var(--yellow); }

  /* ---------- Hero: the painting, rebuilt in CSS ---------- */
  .hero {
    display: grid;
    grid-template-columns: 1.15fr 1.85fr;
    gap: var(--line);
    background: var(--black);
    border-bottom: var(--line) solid var(--black);
    min-height: 78vh;
  }
  .hero-copy {
    background: var(--white);
    padding: clamp(2rem, 5vw, 4.5rem);
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 1.5rem;
  }
  .kicker {
    display: inline-block;
    width: fit-content;
    background: var(--black);
    color: var(--white);
    font-weight: 700;
    letter-spacing: .18em;
    text-transform: uppercase;
    font-size: .75rem;
    padding: .4rem .8rem;
  }
  .hero h1 { font-size: clamp(2rem, 4.5vw, 3.6rem); }
  .hero h1 .c-r { color: var(--red); }
  .hero h1 .c-b { color: var(--blue); }
  .hero h1 .c-y { color: var(--yellow); -webkit-text-stroke: 1px var(--black); }
  .hero p { font-size: clamp(1rem, 1.4vw, 1.2rem); max-width: 46ch; font-weight: 300; }
  .cta {
    display: inline-block;
    width: fit-content;
    font-family: var(--font-display);
    text-transform: uppercase;
    letter-spacing: .05em;
    font-size: 1rem;
    text-decoration: none;
    color: var(--white);
    background: var(--red);
    border: var(--line) solid var(--black);
    box-shadow: -10px 10px 0 var(--black);
    padding: 1rem 1.6rem;
    transition: transform .12s ease, box-shadow .12s ease;
  }
